import { createVoidhashClient } from "@voidhash/react-native";

/**
 * The app's one Voidhash client. Use it as `<voidhash.Provider>`,
 * `voidhash.useHasPerk()` and `voidhash.client`.
 *
 * Debug builds use the test key with simulated purchases; release builds
 * use the production key and the real store. Publishable keys are safe to
 * ship in an app.
 */
export const voidhash = createVoidhashClient(__DEV__ ? "[[.TestKey]]" : "[[.ProductionKey]]", {
  dev: true,[[if .CustomAPI]]
  baseUrl: "[[.APIURL]]",[[end]]
});
